 *
 * @return static
 */
public static function parseFromLocale(string $interval, ?string $locale = null): static
{
    return static::fromString(Carbon::translateTimeString($interval, $locale ?: static::getLocale(), CarbonInterface::DEFAULT_LOCALE));
}

